package pipeline

import (
	"bytes"
	"encoding/json"
	"testing"

	"github.com/abema/go-mp4"
)

// This file re-derives boundaries and error positions from the emitted JSON
// alone, decoding the original generated bytes with go-mp4 directly rather
// than through the scanner used by the pipeline. It exists to catch a summary
// that is internally consistent but wrong about the actual fixture.

type jsonSummary struct {
	Layers []struct {
		Name  string `json:"name"`
		Layer struct {
			StartUs int64 `json:"start_us"`
			EndUs   int64 `json:"end_us"`
		} `json:"layer"`
		Timescale uint32 `json:"timescale"`
	} `json:"layers"`
	DamagedRanges []struct {
		Layer   string `json:"layer"`
		StartUS int64  `json:"start_us"`
		EndUS   int64  `json:"end_us"`
		Kind    string `json:"kind"`
		Segment int    `json:"segment"`
		Offset  uint64 `json:"offset"`
		Known   bool   `json:"position_known"`
	} `json:"damaged_ranges"`
	BoundaryChecks []struct {
		Layer        string  `json:"layer"`
		StartDeltaMS float64 `json:"start_delta_ms"`
		EndDeltaMS   float64 `json:"end_delta_ms"`
		MaxDeltaMS   float64 `json:"max_delta_ms"`
	} `json:"boundary_checks"`
	SyncErrorMS float64 `json:"sync_error_ms"`
}

func TestSummaryMatchesIndependentReparse(t *testing.T) {
	cfg := DefaultConfig()
	summary, err := Run(cfg)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}
	raw, err := json.Marshal(summary)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	var js jsonSummary
	if err := json.Unmarshal(raw, &js); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	sources, err := BuildSources(cfg)
	if err != nil {
		t.Fatalf("BuildSources: %v", err)
	}
	byName := make(map[string]Source)
	for _, s := range sources {
		byName[s.Name] = s
	}

	// 1. Boundaries: independently find the first/last moof tfdt in each
	//    layer's segments and convert with the layer timescale.
	for _, layer := range js.Layers {
		src := byName[layer.Name]
		firstTicks, lastStart, lastDur, ok := independentExtent(t, src)
		if !ok {
			t.Fatalf("%s: no moof decoded", layer.Name)
		}
		wantStart := int64(firstTicks) * 1_000_000 / int64(layer.Timescale)
		if layer.Layer.StartUs != wantStart {
			t.Fatalf("%s start: summary=%d independent=%d", layer.Name, layer.Layer.StartUs, wantStart)
		}
		wantEnd := int64(lastStart+lastDur) * 1_000_000 / int64(layer.Timescale)
		gotEnd := layer.Layer.EndUs
		// The summary rounds each sample boundary to microseconds; allow one
		// tick of rounding.
		tickUs := int64(1_000_000) / int64(layer.Timescale)
		if diff := gotEnd - wantEnd; diff > tickUs || diff < -tickUs {
			t.Fatalf("%s end: summary=%d independent=%d", layer.Name, gotEnd, wantEnd)
		}
	}

	// 3. Boundary checks: recompute the reference deltas from the layer
	//    boundaries and compare to the reported deltas.
	start := make(map[string]int64)
	end := make(map[string]int64)
	for _, l := range js.Layers {
		start[l.Name] = l.Layer.StartUs
		end[l.Name] = l.Layer.EndUs
	}
	var ref string
	for _, c := range js.BoundaryChecks {
		if c.StartDeltaMS == 0 && c.EndDeltaMS == 0 {
			ref = c.Layer
		}
	}
	if ref == "" {
		t.Fatal("no reference layer in checks")
	}
	var maxDelta float64
	for _, c := range js.BoundaryChecks {
		wantStart := float64(start[c.Layer]-start[ref]) / 1000
		wantEnd := float64(end[c.Layer]-end[ref]) / 1000
		if absf(c.StartDeltaMS-wantStart) > 0.001 || absf(c.EndDeltaMS-wantEnd) > 0.001 {
			t.Fatalf("%s deltas: reported (%v,%v) independent (%v,%v)",
				c.Layer, c.StartDeltaMS, c.EndDeltaMS, wantStart, wantEnd)
		}
		if absf(c.MaxDeltaMS) > maxDelta {
			maxDelta = absf(c.MaxDeltaMS)
		}
	}
	if absf(js.SyncErrorMS-maxDelta) > 0.001 {
		t.Fatalf("sync_error_ms=%v but max delta=%v", js.SyncErrorMS, maxDelta)
	}
}

func absf(v float64) float64 {
	if v < 0 {
		return -v
	}
	return v
}

func findSegment(src Source, idx int) []byte {
	for _, s := range src.Segments {
		if s.Index == idx {
			return s.Bytes
		}
	}
	return nil
}

// independentExtent decodes moof/tfdt with go-mp4 without going through the
// cmaf scanner.
func independentExtent(t *testing.T, src Source) (firstTicks uint64, lastStart uint64, lastDur uint64, ok bool) {
	t.Helper()
	var starts []uint64
	var durations []uint64
	for _, seg := range src.Segments {
		buf := seg.Bytes
		for off := 0; off+8 <= len(buf); {
			info, err := mp4.ReadBoxInfo(bytes.NewReader(buf[off:]))
			if err != nil || info.Size == 0 || info.Size > uint64(len(buf)-off) {
				break
			}
			if info.Type == mp4.BoxTypeMoof() {
				payload := buf[off+int(info.HeaderSize) : off+int(info.Size)]
				if ticks, dur, ok := scanMoofIndependently(payload); ok {
					starts = append(starts, ticks)
					durations = append(durations, dur)
				}
			}
			off += int(info.Size)
		}
	}
	if len(starts) == 0 {
		return 0, 0, 0, false
	}
	first := starts[0]
	monotonic := make([]uint64, 0, len(starts))
	monoDur := make([]uint64, 0, len(starts))
	var last uint64
	for i, s := range starts {
		if i > 0 && s < last {
			continue // planted tfdt regression; the fixture's real end is later
		}
		monotonic = append(monotonic, s)
		monoDur = append(monoDur, durations[i])
		last = s
	}
	return first, monotonic[len(monotonic)-1], monoDur[len(monoDur)-1], true
}

// scanMoofIndependently walks one moof payload looking for tfdt and the sum of
// trun sample durations.
func scanMoofIndependently(payload []byte) (ticks, duration uint64, ok bool) {
	var walk func([]byte, int) bool
	walk = func(b []byte, depth int) bool {
		if depth > 4 {
			return false
		}
		for off := 0; off+8 <= len(b); {
			info, err := mp4.ReadBoxInfo(bytes.NewReader(b[off:]))
			if err != nil || info.Size == 0 || info.Size > uint64(len(b)-off) {
				return false
			}
			body := b[off+int(info.HeaderSize) : off+int(info.Size)]
			switch string(info.Type[:]) {
			case "tfdt":
				var tfdt mp4.Tfdt
				if _, err := mp4.Unmarshal(bytes.NewReader(body), uint64(len(body)), &tfdt, mp4.Context{}); err == nil {
					ticks = tfdt.GetBaseMediaDecodeTime()
					ok = true
				}
			case "trun":
				var trun mp4.Trun
				if _, err := mp4.Unmarshal(bytes.NewReader(body), uint64(len(body)), &trun, mp4.Context{}); err == nil {
					for _, e := range trun.Entries {
						duration += uint64(e.SampleDuration)
					}
				}
			case "traf":
				walk(body, depth+1)
			}
			off += int(info.Size)
		}
		return ok
	}
	walk(payload, 0)
	return ticks, duration, ok
}
